package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_isNumber_TriageGen0Test {

    @Test
    public void testIsNumber_NullOrEmpty() {
        assertFalse(NumberUtils.isNumber(null));
        assertFalse(NumberUtils.isNumber(""));
    }

    @Test
    public void testIsNumber_Integers() {
        assertTrue(NumberUtils.isNumber("123"));
        assertTrue(NumberUtils.isNumber("0"));
        assertTrue(NumberUtils.isNumber("-123"));
        assertTrue(NumberUtils.isNumber("123d"));
        assertTrue(NumberUtils.isNumber("123D"));
        assertTrue(NumberUtils.isNumber("123f"));
        assertTrue(NumberUtils.isNumber("123F"));
        assertFalse(NumberUtils.isNumber("abc"));
        assertFalse(NumberUtils.isNumber("12a3"));
    }

    @Test
    public void testIsNumber_Decimals() {
        assertTrue(NumberUtils.isNumber("123.45"));
        assertTrue(NumberUtils.isNumber("123."));
        assertTrue(NumberUtils.isNumber(".123"));
        assertTrue(NumberUtils.isNumber("0.1"));
        assertFalse(NumberUtils.isNumber("1.2.3"));
        assertFalse(NumberUtils.isNumber(".."));
    }

    @Test
    public void testIsNumber_Exponents() {
        assertTrue(NumberUtils.isNumber("123e10"));
        assertTrue(NumberUtils.isNumber("123E10"));
        assertTrue(NumberUtils.isNumber("123e-10"));
        assertTrue(NumberUtils.isNumber("123E+10"));
        assertTrue(NumberUtils.isNumber("-123e10"));
        assertFalse(NumberUtils.isNumber("e10"));
        assertFalse(NumberUtils.isNumber("123e"));
        assertFalse(NumberUtils.isNumber("123e+"));
        assertFalse(NumberUtils.isNumber("123e1.5")); // decimal in exponent not allowed by this logic
        assertFalse(NumberUtils.isNumber("123e10e10"));
    }

    @Test
    public void testIsNumber_Hexadecimal() {
        assertTrue(NumberUtils.isNumber("0x123"));
        assertTrue(NumberUtils.isNumber("0xABC"));
        assertTrue(NumberUtils.isNumber("0xabc"));
        assertTrue(NumberUtils.isNumber("-0x123"));
        assertFalse(NumberUtils.isNumber("0x"));
        assertFalse(NumberUtils.isNumber("0xG12"));
        assertFalse(NumberUtils.isNumber("0x123e")); // hex doesn't allow E suffix in this implementation
    }

    @Test
    public void testIsNumber_TypeQualifiers() {
        // Long qualifiers
        assertTrue(NumberUtils.isNumber("123L"));
        assertTrue(NumberUtils.isNumber("123l"));
        assertFalse(NumberUtils.isNumber("123.4L")); // Not allowed with decimal
        assertFalse(NumberUtils.isNumber("123E10L")); // Not allowed with exponent

        // Float/Double qualifiers
        assertTrue(NumberUtils.isNumber("123.4f"));
        assertTrue(NumberUtils.isNumber("123.4F"));
        assertTrue(NumberUtils.isNumber("123.4d"));
        assertTrue(NumberUtils.isNumber("123.4D"));

        // Invalid qualifiers
        assertFalse(NumberUtils.isNumber("123x"));
    }

    @Test
    public void testIsNumber_EdgeCases() {
        // Sign handling
        assertTrue(NumberUtils.isNumber("-0"));
        assertFalse(NumberUtils.isNumber("-"));
        assertTrue(NumberUtils.isNumber("+123"));

        // Complex valid combinations
        assertTrue(NumberUtils.isNumber("1.2E3"));
        assertTrue(NumberUtils.isNumber("1.2e-3"));

        // Single digit cases
        assertTrue(NumberUtils.isNumber("1"));
        assertTrue(NumberUtils.isNumber("0"));

        // Check logic for allowSigns and foundDigit
        assertFalse(NumberUtils.isNumber("."));
        assertFalse(NumberUtils.isNumber("1e+"));
        assertFalse(NumberUtils.isNumber("1e-"));
    }
}
